 *  then the parent's parent's, up to three levels up; undefined when none has one (or the date is not known yet). */
export function rateOn(rates: Rate[], grade: string, date: string | undefined): string | undefined {
  if (date === undefined) return undefined;
  for (let level = 0; level <= 3; level++) {
    const found = ownRateOn(rates, grade, date, level);
    if (found !== undefined) return found;
  }
  return undefined;
}
