package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.sql.Date;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.function.BiFunction;
import java.util.function.Function;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.ValidateSetting;
import net.officefloor.hq.app.sheet.Sheets;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowCallbackHandler;
import org.springframework.stereotype.Repository;

/**
 * What a statement's figures are worked from: as the store stands now, or as it stood at the end of a date — every
 * change made while the sheet's today was on or before that date, the latest of each winning (see the history tables
 * of V45), with that date standing in for the sheet's today.
 */
@Repository
public class AsOf {

    /** A person and their claims, with the date standing for the sheet's today and the figures in force then
     *  (the rounding mode in force on a date: null for none). */
    public record View(LocalDate today, LocalDate policyDate, BigDecimal cap, Person person, List<Claim> claims,
            BiFunction<String, LocalDate, BigDecimal> rate, Function<LocalDate, BigDecimal> floor,
            Function<LocalDate, BigDecimal> latePct, Function<LocalDate, java.math.RoundingMode> rounding) {
    }

    private record RateRow(BigDecimal rate, LocalDate from, LocalDate to) {
    }

    private final JdbcTemplate jdbc;
    private final Claims claims;
    private final Rates rates;
    private final Settings settings;
    private final Sheets sheets;

    public AsOf(JdbcTemplate jdbc, Claims claims, Rates rates, Settings settings, Sheets sheets) {
        this.jdbc = jdbc;
        this.claims = claims;
        this.rates = rates;
        this.settings = settings;
        this.sheets = sheets;
        AsOf.View view = date == null ? asOf.now(person) : asOf.at(person, date);
        LocalDate today = view.today();
        Person then = view.person();
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean anyFigure = false;
        int counted = 0;
        // The figure each counting claim is bound to, by id (a null figure: n/a).
        Map<Long, BigDecimal> bound = new HashMap<>();
        for (Claim claim : view.claims()) {
            if (!then.countsLive(claim, today)) {
                continue;
            }
            RoundingMode rounding = Rounding.of(claim, view.policyDate(), view.rounding());
            BigDecimal fixed = ClaimResponse.fixedDue(claim);
            // A bound claim keeps its figure (even n/a); a live one is worked at the rate on its date (unfloored).
            BigDecimal figure = fixed != null || claim.isBound() ? fixed
                    : Rates.due(claim.getAmount(), view.rate().apply(then.gradeOn(claim.getDate()), claim.getDate()), rounding);
            if (figure != null) {
                anyFigure = true;
                total = total.add(LateCharge.due(claim, figure, view.floor().apply(claim.getDate()), view.latePct(),
                        today, rounding));
            }
            bound.put(claim.getId(), figure);
            counted++;
        }
        for (Claim claim : date == null ? view.claims() : claims.ofPerson(sheetId, person.getId())) {
            claim.setStated(bound.containsKey(claim.getId()));
            claim.setStatedDue(bound.get(claim.getId()));
            claims.bind(claim);
        }
        // n/a only when no claim keeps or gets a figure (each at the grade in force on its date).
        boolean na = !anyFigure && view.rate().apply(then.getGrade(), today) == null;
        BigDecimal dueTotal = na ? null : Settings.capped(total, view.cap());
        person.setStatementCount(person.getStatementCount() + 1);
        person.setStatedTotal(dueTotal);
        person.setStatementDate(today);
        people.saveStatement(person);
        people.addStatement(person);
        statement.set(new Statement(dueTotal, counted, date));
    }

